package net.civeira.phylax.feature.observe.observedissuealias.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observedissuealias.domain.ObservedIssueAlias;
import net.civeira.phylax.feature.observe.observedissuealias.domain.event.ObservedIssueAliasEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservedIssueAliasEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservedIssueAliasEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservedIssueAlias entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
